/// Decode-then-encode by type name. Used only by the shared conformance runner.
pub fn conformance_round_trip(type_name: &str, value: &Value) -> Option<Result<Value, DecodeError>> {
    match type_name {
        "Direction" => Some(decode_direction(value, "$").map(|decoded| encode_direction(&decoded))),
        "Preference" => Some(decode_preference(value, "$").map(|decoded| encode_preference(&decoded))),
        "PreferenceValue" => Some(decode_preference_value(value, "$").map(|decoded| encode_preference_value(&decoded))),
        "Environment" => Some(decode_environment(value, "$").map(|decoded| encode_environment(&decoded))),
        "NumberStyle" => Some(decode_number_style(value, "$").map(|decoded| encode_number_style(&decoded))),
        "DateStyle" => Some(decode_date_style(value, "$").map(|decoded| encode_date_style(&decoded))),
        "RelativeUnit" => Some(decode_relative_unit(value, "$").map(|decoded| encode_relative_unit(&decoded))),
        "ListType" => Some(decode_list_type(value, "$").map(|decoded| encode_list_type(&decoded))),
        "FormatItem" => Some(decode_format_item(value, "$").map(|decoded| encode_format_item(&decoded))),
        "EnvironmentRequest" => Some(decode_environment_request(value, "$").map(|decoded| encode_environment_request(&decoded))),
        "EnvironmentResult" => Some(decode_environment_result(value, "$").map(|decoded| encode_environment_result(&decoded))),
        "EnvironmentFact" => Some(decode_environment_fact(value, "$").map(|decoded| encode_environment_fact(&decoded))),
        _ => None,
    }
}
